	{"collect_herb_lv25._90_say", "70:36FC756C", "Oh, you've found one![ENTER]Let me have a look at it... "},
	{"collect_herb_lv4._100_npcChat", "18:3BF7F8E1", "Peach Blossoms "},
	{"collect_herb_lv4._10_sendLetter", "23:4EFC8B3D", "Biologist's Analysis (lv. 4)"},
