	{"beta.equipment.already", "17:DCD0EED4", "You have already collected your equipment."},
	{"beta.equipment.ask", "96:484669D1", "Do you want equipment? You can only do this once per character. For which character level do you want to receive equipment?"},
	{"beta.equipment.chat", "16:B06FED23", "BETA: Collect equipment"},
	{"beta.equipment.low_lvl", "50:B364C109", "Your level must be equal to or higher than the one you chose."},
	{"beta.equipment.success", "10:E6567F41", "Equipment granted."},
	{"beta.gold.ask", "18:A00DA6D5", "Shall I give you Yang?"},
	{"beta.gold.chat", "21:EEF8242F", "BETA: Give me some Yang"},
	{"beta.gold.info", "85:BE1D1B59", "At your current level you will receive %s Yang. You can collect it every 1 day (except in stage 4)."},
	{"beta.gold.success", "22:E8252F80", "Yang granted successfully."},
	{"beta.gold.wait", "41:FF67946E", "You must wait %s before you can collect it again."},
