	{"beta.itemshop.chat", "18:F01581A0", "BETA: Give me a DR Voucher"},
	{"beta.itemshop.say", "23:EA72BC3D", "Don't blow it all on nonsense!"},
	{"beta.level_up.ask", "13:709C5F2E", "Shall I level you up?"},
	{"beta.level_up.ask2", "36:D1700050", "Are you sure you want me to level you up to level %d?"},
