	{"beta.shop.high_item", "8:50ACB1F0", "Items +9"},
	{"beta.shop.high_item2", "15:328E9094", "Items +9 and Spirit Stones +4"},
	{"beta.shop.high_weapon", "16:7F80E6B5", "Weapons lv. 70/75"},
