	{"beta.shop.refine_item_shop1", "16:F945F42D", "Upgrade materials M1/M2"},
	{"beta.shop.refine_item_shop2", "32:F0F45F43", "Upgrade materials Valley/Hwang/Desert"},
	{"beta.shop.refine_item_shop3", "30:09F31782", "Upgrade materials Sohan/Hell/Forest/DT"},
	{"beta.skill.ask", "127:EBAF7B4D", "Do you want me to set all your class skills to G1? They must be between M1 and M10 for me to change their level."},
