	{"beta.skill_pvp.ask", "126:E816264E", "Do you want me to set all your class skills to P? They must be between M1 and G10 for me to change their level."},
	{"beta.skill_pvp.chat", "23:3302A7E4", "BETA: Set skills to P"},
	{"beta.skill_pvp.fail", "49:8A0783BE", "I found no skill that I could set to P."},
